%% Draw cursor-control trajectories and summary
% July23rd2026
%
% This script is intentionally thin:
%   1. Load g##_trialwise.mat.
%   2. Use cursor_control_result_viewer.m for the main 6x20 trajectory
%      viewer, including the animation panel and UI controls embedded in
%      the central blank space.
%   3. Draw only the distance-error / movement-ratio summary as a separate
%      figure.
%
% Required files in this folder:
%   cursor_control_result_viewer.m
%
% Required data:
%   AnalyzedData/g##_trialwise.mat generated by convert_csv2mat.m

clear; clc;

baseDir = cd;
addpath(baseDir);

analyzedDataDir = fullfile(baseDir, "AnalyzedData");
if isfolder(analyzedDataDir)
    addpath(analyzedDataDir);
end

g = 23;
viewConfig = taskVisualizationConfig(g);
matPath = fullfile(analyzedDataDir, "g" + string(g) + "_trialwise.mat");

if ~isfile(matPath)
    [fileName, folderName] = uigetfile("*.mat", "Select g##_trialwise.mat");
    if isequal(fileName, 0)
        error("No MAT file selected.");
    end
    matPath = fullfile(folderName, fileName);
end

S = load(matPath);
if ~isfield(S, "trialData")
    error("Selected MAT file does not contain trialData: %s", matPath);
end
trialData = S.trialData;
viewConfig = updateTaskVisualizationConfigFromData(viewConfig, trialData);
phaseTrials = inferPhaseTrials(trialData, viewConfig);
viewConfig.baselinePreTrialNumbers = phaseTrials.baselinePreTrialNumbers;
viewConfig.sharedTrialNumbers = phaseTrials.sharedTrialNumbers;
viewConfig.baselinePostTrialNumbers = phaseTrials.baselinePostTrialNumbers;

%% Main trajectory viewer
% This creates the intended Figure 1: static 6x20 tiled layout plus the
% embedded animation panel and UI controls in rows 1-3 / columns 6-15.

if exist("cursor_control_result_viewer", "file") ~= 2
    error("cursor_control_result_viewer.m was not found on the MATLAB path.");
end

cursor_control_result_viewer(matPath, viewConfig);

%% Distance error & Movement ratio summary

[M, trialNumbers] = trialDataToMatrices(trialData, viewConfig);
nTrials = numel(trialNumbers);

baselinePreIdx = find(ismember(trialNumbers, phaseTrials.baselinePreTrialNumbers));
sharedIdx = find(ismember(trialNumbers, phaseTrials.sharedTrialNumbers));
baselinePostIdx = find(ismember(trialNumbers, phaseTrials.baselinePostTrialNumbers));

s1_err = mean(M.test1_error, 1, "omitnan");
s2_err = mean(M.test2_error, 1, "omitnan");
sh_err = mean(M.sharedError, 1, "omitnan");
movementRatio = computeMovementRatio(M, viewConfig);

figure("Color", "w", "Name", "Distance error and movement ratio", ...
    "Position", [300 120 900 520]);

subplot(2, 1, 1);
hold on;
plot(trialNumbers(baselinePreIdx), s1_err(baselinePreIdx), "r-", "LineWidth", 2);
plot(trialNumbers(baselinePreIdx), s2_err(baselinePreIdx), "b-", "LineWidth", 2);
plot(trialNumbers(sharedIdx), sh_err(sharedIdx), "g-", "LineWidth", 2);
plot(trialNumbers(baselinePostIdx), s1_err(baselinePostIdx), "r-", "LineWidth", 2);
plot(trialNumbers(baselinePostIdx), s2_err(baselinePostIdx), "b-", "LineWidth", 2);
legend({"subj1", "subj2", "joint", "", ""}, "Location", "best");
xlabel("Trial");
xlim([min(trialNumbers) - 1 max(trialNumbers) + 1]);
ylim([0 0.1]);
ylabel("Distance error (au)");
title("Distance between target and cursor (avg across time)");
box on;

subplot(2, 1, 2);
hold on;
plot(trialNumbers(sharedIdx), movementRatio(sharedIdx), "k-", "LineWidth", 2);
yline(0.5, "k--", "Equal");
xlabel("Trial");
xlim([min(trialNumbers) - 1 max(trialNumbers) + 1]);
ylim([0 1]);
ylabel("Movement ratio, P1/(P1+P2)");
title("Within-pair movement bias during shared trials");
box on;

function [M, trialNumbers] = trialDataToMatrices(trialData, viewConfig)
    trialNumbers = [trialData.trialNumber];
    nTrials = numel(trialData);
    nMax = max(arrayfun(@(tr) numel(tr.timeFromTrialStartSec), trialData));

    names = [
        "timeFromTrialStartSec"
        "test1_HandX"
        "test1_HandY"
        "test1_cursorX"
        "test1_cursorY"
        "test2_HandX"
        "test2_HandY"
        "test2_cursorX"
        "test2_cursorY"
        "sharedCursorX"
        "sharedCursorY"
        "targetX"
        "targetY"
        "test1_targetX"
        "test1_targetY"
        "test2_targetX"
        "test2_targetY"
    ];

    for ni = 1:numel(names)
        M.(names(ni)) = nan(nMax, nTrials);
    end

    for ti = 1:nTrials
        tr = trialData(ti);
        for ni = 1:numel(names)
            name = names(ni);
            v = trialFieldWithFallback(tr, name);
            M.(name)(1:numel(v), ti) = v(:);
        end
    end

    if viewConfig.rotateParticipant2
        isSharedTrial = false(1, nTrials);
        for ti = 1:nTrials
            isSharedTrial(ti) = isSharedPhaseTrial(trialData(ti), viewConfig);
        end

        originalTest2X = M.test2_cursorX(:, isSharedTrial);
        originalTest2Y = M.test2_cursorY(:, isSharedTrial);
        originalTest2HandX = M.test2_HandX(:, isSharedTrial);
        originalTest2HandY = M.test2_HandY(:, isSharedTrial);
        M.test2_cursorX(:, isSharedTrial) = originalTest2Y;
        M.test2_cursorY(:, isSharedTrial) = 1 - originalTest2X;
        rotatedTest2HandX = originalTest2HandY;

        if viewConfig.task8SharedScale == "half"
            M.sharedCursorX(:, isSharedTrial) = 0.5 + 0.5 * (rotatedTest2HandX - 0.5);
            M.sharedCursorY(:, isSharedTrial) = 0.5 + 0.5 * (M.test1_HandY(:, isSharedTrial) - 0.5);
        elseif viewConfig.task8SharedScale == "full"
            M.sharedCursorX(:, isSharedTrial) = rotatedTest2HandX;
            M.sharedCursorY(:, isSharedTrial) = M.test1_HandY(:, isSharedTrial);
        end
    end

    test1Error = hypot(M.test1_cursorX - M.test1_targetX, M.test1_cursorY - M.test1_targetY);
    test2Error = hypot(M.test2_cursorX - M.test2_targetX, M.test2_cursorY - M.test2_targetY);

    if isfield(viewConfig, "swapPair") && viewConfig.swapPair
        M.test1_error = test2Error;
        M.test2_error = test1Error;
    else
        M.test1_error = test1Error;
        M.test2_error = test2Error;
    end

    M.sharedError = hypot(M.sharedCursorX - M.targetX, M.sharedCursorY - M.targetY);
    M.test1_error(M.test1_error > 0.2) = nan;
    M.test2_error(M.test2_error > 0.2) = nan;
    M.sharedError(M.sharedError > 0.2) = nan;
end

function movementRatio = computeMovementRatio(M, viewConfig)
    nTrials = size(M.test1_HandX, 2);
    movementRatio = nan(1, nTrials);

    for ti = 1:nTrials
        move1 = trajectoryLength(M.test1_HandX(:, ti), M.test1_HandY(:, ti));
        move2 = trajectoryLength(M.test2_HandX(:, ti), M.test2_HandY(:, ti));
        movementRatio(ti) = move1 / (move1 + move2);
        if isfield(viewConfig, "swapPair") && viewConfig.swapPair
            movementRatio(ti) = 1 - movementRatio(ti);
        end
    end
end

function viewConfig = taskVisualizationConfig(g)
    viewConfig = struct();
    viewConfig.groupNumber = g;
    viewConfig.rotateParticipant2 = false;
    viewConfig.task8SharedScale = "recorded";
    viewConfig.swapPair = ismember(g, [1 4 22 23]);

    if g >= 5 && g <= 7
        viewConfig.rotateParticipant2 = true;
        viewConfig.task8SharedScale = "half";
    elseif g >= 8 && g <= 12
        viewConfig.rotateParticipant2 = true;
        viewConfig.task8SharedScale = "full";
    end
end

function viewConfig = updateTaskVisualizationConfigFromData(viewConfig, trialData)
    if isfinite(viewConfig.groupNumber) && viewConfig.groupNumber >= 1 && viewConfig.groupNumber <= 12
        return;
    end

    isTask8 = any(arrayfun(@(tr) hasPhaseText(tr, "taskType", "task8") ...
        || hasPhaseText(tr, "cursorDisturbanceType", "axis-aligned-gain-plus-rotation"), trialData));
    if isTask8
        viewConfig.rotateParticipant2 = true;
        viewConfig.task8SharedScale = "full";
    end
end

function phaseTrials = inferPhaseTrials(trialData, viewConfig)
    trialNumbers = [trialData.trialNumber];
    nTrials = numel(trialNumbers);

    if isfield(viewConfig, "baselinePreTrialNumbers") ...
            && isfield(viewConfig, "sharedTrialNumbers") ...
            && isfield(viewConfig, "baselinePostTrialNumbers")
        phaseTrials.baselinePreTrialNumbers = viewConfig.baselinePreTrialNumbers;
        phaseTrials.sharedTrialNumbers = viewConfig.sharedTrialNumbers;
        phaseTrials.baselinePostTrialNumbers = viewConfig.baselinePostTrialNumbers;
        return;
    end

    sharedMask = false(1, nTrials);
    for ti = 1:nTrials
        sharedMask(ti) = hasPhase(trialData(ti), "shared");
    end

    if any(sharedMask)
        firstShared = find(sharedMask, 1, "first");
        lastShared = find(sharedMask, 1, "last");
        phaseTrials.baselinePreTrialNumbers = trialNumbers(1:firstShared - 1);
        phaseTrials.sharedTrialNumbers = trialNumbers(firstShared:lastShared);
        phaseTrials.baselinePostTrialNumbers = trialNumbers(lastShared + 1:end);
        return;
    end

    if nTrials == 30
        nPre = 5;
        nShared = 20;
    elseif nTrials == 20
        nPre = 3;
        nShared = 14;
    else
        nPre = min(5, max(1, floor(nTrials * 0.15)));
        nPost = nPre;
        nShared = max(0, nTrials - nPre - nPost);
    end

    nPre = min(nPre, nTrials);
    nShared = min(nShared, max(0, nTrials - nPre));
    nPostStart = nPre + nShared + 1;

    phaseTrials.baselinePreTrialNumbers = trialNumbers(1:nPre);
    phaseTrials.sharedTrialNumbers = trialNumbers(nPre + 1:nPre + nShared);
    phaseTrials.baselinePostTrialNumbers = trialNumbers(nPostStart:end);
end

function tf = isSharedPhaseTrial(tr, viewConfig)
    tf = false;
    if isfield(tr, "phase")
        values = string(tr.phase);
        tf = any(values == "shared");
    end
    if ~tf && isfield(tr, "trialNumber")
        tf = any(tr.trialNumber == viewConfig.sharedTrialNumbers);
    end
end

function tf = hasPhase(tr, expected)
    tf = false;
    if ~isfield(tr, "phase")
        return;
    end
    values = string(tr.phase);
    values = values(strlength(values) > 0 & values ~= "missing" & values ~= "unknown");
    tf = any(values == string(expected));
end

function tf = hasPhaseText(tr, fieldName, expected)
    tf = false;
    if ~isfield(tr, fieldName)
        return;
    end
    values = string(tr.(fieldName));
    values = values(strlength(values) > 0 & values ~= "missing" & values ~= "unknown");
    tf = any(values == string(expected));
end

function v = trialFieldWithFallback(tr, name)
    name = string(name);
    if isfield(tr, char(name))
        v = tr.(char(name));
        return;
    end

    switch name
        case "test1_HandX"
            v = firstExistingTrialField(tr, ["test1_CursorX", "test1_cursorX"]);
        case "test1_HandY"
            v = firstExistingTrialField(tr, ["test1_CursorY", "test1_cursorY"]);
        case "test2_HandX"
            v = firstExistingTrialField(tr, ["test2_CursorX", "test2_cursorX"]);
        case "test2_HandY"
            v = firstExistingTrialField(tr, ["test2_CursorY", "test2_cursorY"]);
        case "test1_targetX"
            v = firstExistingTrialField(tr, ["targetX"]);
        case "test1_targetY"
            v = firstExistingTrialField(tr, ["targetY"]);
        case "test2_targetX"
            v = firstExistingTrialField(tr, ["targetX"]);
        case "test2_targetY"
            v = firstExistingTrialField(tr, ["targetY"]);
        otherwise
            v = nan(0, 1);
    end
end

function v = firstExistingTrialField(tr, names)
    v = nan(0, 1);
    for ii = 1:numel(names)
        fieldName = char(names(ii));
        if isfield(tr, fieldName)
            v = tr.(fieldName);
            return;
        end
    end
end

function L = trajectoryLength(x, y)
    x = x(:);
    y = y(:);

    ok = isfinite(x) & isfinite(y);
    x = x(ok);
    y = y(ok);

    if numel(x) < 2
        L = nan;
        return;
    end

    L = sum(hypot(diff(x), diff(y)), "omitnan");
end
